today = fields.Date.today()
memberships = model.search([('state', '=', 'active'), ('end_date', '>=', today)])
for membership in memberships:
    if membership.billing_cycle == 'monthly':
        last_invoice = membership.invoice_ids.filtered(lambda i: i.move_type == 'out_invoice').sorted('invoice_date', reverse=True)[:1]
        if not last_invoice or (last_invoice.invoice_date + relativedelta(months=1)).replace(day=1) <= today:
            membership._create_invoice()
    elif membership.billing_cycle == 'yearly':
        last_invoice = membership.invoice_ids.filtered(lambda i: i.move_type == 'out_invoice').sorted('invoice_date', reverse=True)[:1]
        if not last_invoice or (last_invoice.invoice_date + relativedelta(years=1)).replace(month=1, day=1) <= today:
            membership._create_invoice()
